sys_script_client.script:
function onLoad() {
   g_form.addInfoMessage("Welcome to the Event Record form!");

   if(!g_form.isNewRecord()){
		var _eventSysId = g_form.getUniqueValue();

		var _eventGAjax = new GlideAjax('EventUtilsCS');
		_eventGAjax.addParam('sysparm_name', 'getEventDetails');
		_eventGAjax.addParam('sysparm_eventId', _eventSysId);

		_eventGAjax.getXMLAnswer(function(response){
			response = JSON.parse(response);
			g_form.addInfoMessage(
				"The event '"+response.eventName+"' is "+((response.vip==true)? 'an VIP':'not an VIP')+" and date is: "+response.eventDate+"."
			);
		});
   }
}
